<?php

defined('ABSPATH') || exit;

final class PLDR_Future_Rooms {
    public static function create(int $edition_id,int $page,array $anchor=array()) { global $wpdb;$uid=get_current_user_id();if(!$uid)return PLDR_Core::machine_error('pldr_room_login','Log in to create a scholarly reading room.',401);$edition=PLDR_Future_Data::require_edition($edition_id);if(is_wp_error($edition))return $edition;$doc=PLDR_Core::document((int)$edition['document_id']);if($doc && 'patient-cases'===$doc['category'] && !apply_filters('pldr_patient_case_reading_room_allowed',false,$edition_id,$doc))return PLDR_Core::machine_error('pldr_room_patient_case','Patient-case documents require separate privacy approval before a reading room can be created.',403);$page=max(1,min((int)$edition['pages'],$page));$context=array('file'=>12,'edition_id'=>$edition_id,'document_id'=>$edition['public_id'],'page'=>$page,'anchor'=>$anchor,'source_url'=>PLDR_Core::route_url('read',array('id'=>$edition['public_id'])));$provider=apply_filters('pldr_create_reading_room_provider',null,$uid,$context);$room_key=PLDR_Core::uuid();$provider_ref=is_array($provider)?sanitize_text_field((string)($provider['reference']??'')):'';$status=$provider_ref?'active':'pending-provider';$wpdb->insert(PLDR_Core::table('room_contexts'),array('room_key'=>$room_key,'edition_id'=>$edition_id,'created_by'=>$uid,'page_number'=>$page,'anchor_json'=>wp_json_encode($anchor),'provider_ref'=>$provider_ref,'status'=>$status,'created_at'=>PLDR_Core::now(),'updated_at'=>PLDR_Core::now()));PLDR_Core::emit('PDFReadingRoomRequested.v1','edition',$edition_id,array('room_key'=>$room_key,'document_id'=>$edition['public_id'],'page'=>$page,'provider_ref'=>$provider_ref));return array('room_key'=>$room_key,'status'=>$status,'provider_ref'=>$provider_ref,'messaging_owner'=>'File 17 / shared communication contract','file_12_owns_only_anchor_context'=>true); }
}
